format_data:
[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Purchase Order</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<style>
    [document-status] {
        display: none;
    }

    .print-heading {
        display: none;
    }
</style>

<div style="width: 100%;float: left;padding: 0 5px;">
    <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Ref : {{doc.name}}</p>
    <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Date : {% if doc.creation %} {{frappe.utils.getdate(doc.creation).strftime('%d/%m/%Y')}} {% endif %}</p>
</div>

{% set supplier_data = {"supplier_name":"","company":"", "transaction_date":""} %}

<div style="width: 100%;float: left;padding: 0 5px;">
    <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">To</p>
    {% if doc.original_purchase_order %}
        {% set get_po = frappe.get_doc('Purchase Order', doc.original_purchase_order) %}
        {% set _ = supplier_data.update({"supplier_name":get_po.supplier_name}) %}
        {% set _ = supplier_data.update({"company":get_po.company}) %}
        {% set _ = supplier_data.update({"transaction_date":get_po.transaction_date}) %}
    <p style="font-size: 13px;color: black;text-align: left;">
        {% if get_po.supplier_name %} {{get_po.supplier_name}} {% endif %} <br>
        {% if get_po.supplier_address %}
            {% set supplier_address = frappe.get_doc('Address', get_po.supplier_address) %}
            {% if supplier_address.address_line1 %} {{supplier_address.address_line1}}<br>{% endif %}
            {% if supplier_address.address_line2 %} {{supplier_address.address_line2}}<br>{% endif %}
            {% if supplier_address.city %} {{supplier_address.city}},<br>{% endif %}
            {% if supplier_address.state %} {{supplier_address.state}},<br>{% endif %}
            {% if supplier_address.pincode %} Pincode : {{supplier_address.pincode}} {% endif %}
        {% endif %}
    </p>
    {% endif %}
</div>

<div style="width: 100%;float: left;padding: 0 5px;margin-top: 5px;">
    <p style="font-size: 13px;color: black;text-align: left;text-decoration: underline;">Attention : <b>
        {% if supplier_data.supplier_name %}
            {{supplier_data.supplier_name}}
        {% endif %}
    </b></p>
    <p style="font-size: 13px;color: black;text-align: left;">
        SUB : THE RATE HAS BEEN CHANGED FROM 950/MT TO 975/MT
    </p>
    <p style="font-size: 13px;color: black;text-align: left;">
        Ref: Your Work order reference no: <b>{% if doc.original_purchase_order %} {{doc.original_purchase_order}} {% endif %}</b>Dated {% if supplier_data.transaction_date %} {{frappe.utils.getdate(supplier_data.transaction_date).strftime('%d/%m/%Y')}} {% endif %}
    </p>
</div>

{% set total_qty = {"qty":0.0} %}
{% if doc.items %}
    {% for row in doc.items %}
        {% set _ = total_qty.update({"qty":total_qty.qty + row.quantity}) %}
    {% endfor %}
{% endif %}

<div style="width: 100%;float: left;padding: 0 5px;margin-top: 5px;">
    <p style="font-size: 13px;color: black;text-align: left;">Dear Sir,</p>
    <p style="font-size: 13px;color: black;text-align: left;">
        This has the reference to above cited subject and reference this work order amendment letter to be read always in
        conjunction with the original work order <b>{% if doc.original_purchase_order %} {{doc.original_purchase_order}} {% endif %}</b> and dated <b>{% if supplier_data.transaction_date %} {{frappe.utils.getdate(supplier_data.transaction_date).strftime('%d/%m/%Y')}} {% endif %}</b>
    </p>
    <p style="font-size: 13px;color: black;text-align: left;">
        The below amendments are to be made to the existing SO:
    </p>
</div>

<div style="width: 100%;float: left;margin-top: 10px;">
    <table style="width: 100%;">
        <thead>
            <th style="font-size: 13px;color: black;font-weight: 600;border: 1px solid black;text-align: center;">S.No</th>
            <th style="font-size: 13px;color: black;font-weight: 600;border: 1px solid black;text-align: center;">Description of Work</th>
            <th style="font-size: 13px;color: black;font-weight: 600;border: 1px solid black;text-align: center;">UOM</th>
            <th style="font-size: 13px;color: black;font-weight: 600;border: 1px solid black;text-align: center;">Quantity</th>
            <th style="font-size: 13px;color: black;font-weight: 600;border: 1px solid black;text-align: center;">Previous Rate</th>
            <th style="font-size: 13px;color: black;font-weight: 600;border: 1px solid black;text-align: center;">Amended Rate</th>
        </thead>
        <tbody>
            {% for row in doc.items %}
            <tr>
                <td style="font-size: 13px;color: black;border: 1px solid black;text-align: center;">{{loop.index}}</td>
                <td style="font-size: 13px;color: black;border: 1px solid black;text-align: left;">{% if row.item_name %} {{row.item_name}} {% endif %}</td>
                <td style="font-size: 13px;color: black;border: 1px solid black;text-align: center;"></td>
                <td style="font-size: 13px;color: black;border: 1px solid black;text-align: right;">{% if row.quantity %} {{row.quantity}} {% endif %}</td>
                <td style="font-size: 13px;color: black;border: 1px solid black;text-align: right;">{% if row.rate_per_unit %} {{frappe.utils.fmt_money(row.rate_per_unit)}} {% endif %}</td>
                <td style="font-size: 13px;color: black;border: 1px solid black;text-align: center;">{% if row.revised_rate %} {{frappe.utils.fmt_money(row.revised_rate)}} {% endif %}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
</div>

<div style="width: 100%;float: left;padding:  0 5px;">
    <p style="font-size: 13px;color: black;text-align: left;">The above Amendment shall be in force from <b>{% if doc.contract_valid_till %} {{frappe.utils.getdate(doc.contract_valid_till).strftime('%d/%m/%Y')}} {% endif %}</b></p>
    <p style="font-size: 13px;color: black;text-align: left;">
        All the other terms and conditions will remain the same as the original work order <b>{{doc.original_purchase_order}}</b>
    </p>
    <p style="font-size: 13px;color: black;text-align: left;">
        Please acknowledge the receipt of the Work Order and send us a duly signed copy at the earnest.
    </p>
</div>

<div style="width: 100%;float: left;padding: 0 5px;margin-top: 10px;">
    <p style="font-size: 13px;color: black;text-align: left;">Thanking You,</p>
    <img src="/files/refex_signature_seal.JPG" alt="" style="margin-top: 20px;">
</div>

<div style="width: 100%;float: left;padding: 0 5px;margin-top: 20px;">
    <div style="width: 50%;float: left;">
        <div style="border-bottom: 1px solid black;">&nbsp;</div>
        <p style="font-size: 13px;color: black;text-align: center;font-weight: 600;">
            {% if supplier_data.company %}
                ({{supplier_data.company}})
            {% endif %}
        </p>
    </div>
    <div style="width: 50%;float: right;">
        <p style="font-size: 13px;color: black;text-align: center;font-weight: 600;">Acknowledged By</p>
        <p style="font-size: 13px;color: black;text-align: center;font-weight: 600;">
            {% if supplier_data.supplier_name %}
                {{supplier_data.supplier_name}}
            {% endif %}
        </p>
    </div>
</div>"}]
